#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 vector<vector<int>> getAncestors(int n,vector<vector<int>>& edges) {
  vector<vector<int>> g(n),ans(n);vector<int> indeg(n);vector<set<int>> ancestors(n);
  for(auto&e:edges){g[e[0]].push_back(e[1]);++indeg[e[1]];}
  queue<int> q;for(int i=0;i<n;++i)if(!indeg[i])q.push(i);
  while(!q.empty()){int u=q.front();q.pop();for(int v:g[u]){
   ancestors[v].insert(u);ancestors[v].insert(ancestors[u].begin(),ancestors[u].end());
   if(--indeg[v]==0)q.push(v);
  }}
  for(int i=0;i<n;++i)ans[i]=vector<int>(ancestors[i].begin(),ancestors[i].end());return ans;
 }
};
